info.description:
a cute YouTube logo/* Hide the default YouTube logo */
ytd-topbar-logo-renderer svg {
  display: none !important;
}

/* Apply the new Sonic & Amy Rose GIF */
ytd-topbar-logo-renderer {
  width: 56px !important;
  height: 56px !important;

  background-image: url("https://media.tenor.com/mzSYD4KqNv0AAAAi/sonic-the-hedgehog-amy-rose.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;

  image-rendering: pixelated;
}

/* Optional hover bounce */
ytd-topbar-logo-renderer:hover {
  animation: sonicBounce 0.4s infinite alternate;
}

@keyframes sonicBounce {
  from { transform: translateY(0); }
  to   { transform: translateY(-4px); }
}

